('bmlt-moleculargenetics1-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"PCR amplification is primarily used to:","translation":"","options":["Amplify a specific DNA sequence","Translate RNA into protein","Separate proteins by charge","Stain chromosomes"],"correctIndex":0,"explanation":"PCR produces many copies of a target DNA region.","explanationNe":"PCR ले लक्षित DNA क्षेत्रका धेरै प्रतिहरू बनाउँछ।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
