('bmlt-moleculargenetics1-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"The extension step of standard PCR is commonly performed near:","translation":"","options":["4°C","25°C","72°C","100°C"],"correctIndex":2,"explanation":"Many thermostable polymerases extend efficiently around 72°C.","explanationNe":"धेरै thermostable polymerase करिब 72°C मा राम्रोसँग काम गर्छन्।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
('bmlt-moleculargenetics1-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"A primer in PCR is:","translation":"","options":["A short oligonucleotide that provides a starting point","A fluorescent microscope filter","A protein digestion enzyme","A DNA extraction solvent"],"correctIndex":0,"explanation":"DNA polymerase requires a primer with a free 3′-OH group.","explanationNe":"DNA polymerase लाई free 3′-OH भएको primer चाहिन्छ।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
('bmlt-moleculargenetics1-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"A positive control in PCR should:","translation":"","options":["Contain known target DNA and produce expected amplification","Contain no template DNA","Replace the patient sample","Prevent all contamination"],"correctIndex":0,"explanation":"The positive control confirms that the amplification system can work.","explanationNe":"Positive control ले PCR प्रणाली काम गरिरहेको पुष्टि गर्छ।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
('bmlt-moleculargenetics1-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"A no-template control is used mainly to detect:","translation":"","options":["Contamination in reagents or setup","Patient antibody level","DNA fragment size","Primer melting temperature"],"correctIndex":0,"explanation":"Unexpected amplification in a no-template control suggests contamination.","explanationNe":"No-template control मा amplification आए contamination शंका हुन्छ।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
('bmlt-moleculargenetics1-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"Agarose gel electrophoresis separates DNA mainly by:","translation":"","options":["Fragment size","Antibody class","Enzyme activity","Cell viability"],"correctIndex":0,"explanation":"Smaller DNA fragments generally migrate farther through agarose.","explanationNe":"सानो DNA fragment agarose gel मा सामान्यतया बढी टाढा जान्छ।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
