('bmlt-moleculargenetics1-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"In real-time PCR, a lower Ct/Cq value generally indicates:","translation":"","options":["More starting target nucleic acid","Less starting target nucleic acid","No amplification","Only longer DNA fragments"],"correctIndex":0,"explanation":"More starting target usually crosses the fluorescence threshold earlier.","explanationNe":"धेरै starting target हुँदा fluorescence threshold चाँडै पार हुन्छ।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
('bmlt-moleculargenetics1-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"RT-PCR begins by converting:","translation":"","options":["DNA to protein","RNA into complementary DNA","Protein into RNA","Lipid into DNA"],"correctIndex":1,"explanation":"Reverse transcriptase synthesizes cDNA from an RNA template.","explanationNe":"Reverse transcriptase ले RNA बाट cDNA बनाउँछ।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
('bmlt-moleculargenetics1-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"A common use of RT-qPCR is:","translation":"","options":["Quantifying RNA expression or detecting RNA targets","Measuring serum sodium directly","Counting red cells manually","Determining blood group by agglutination"],"correctIndex":0,"explanation":"RNA is converted to cDNA and quantified during amplification.","explanationNe":"RNA लाई cDNA बनाएर amplification मार्फत मापन गरिन्छ।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
('bmlt-moleculargenetics1-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"A mutation is best defined as:","translation":"","options":["A change in the nucleotide sequence","A normal PCR cycle","A protein stain","A type of centrifuge"],"correctIndex":0,"explanation":"A mutation is a change in genetic sequence; its effect may vary.","explanationNe":"Mutation genetic sequence मा परिवर्तन हो; प्रभाव फरक हुन सक्छ।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
('bmlt-moleculargenetics1-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"A single nucleotide polymorphism (SNP) involves:","translation":"","options":["Variation at one nucleotide position","Loss of an entire chromosome in every case","Only a protein amino acid","A bacterial colony count"],"correctIndex":0,"explanation":"A SNP is a single-base variation at a genomic position.","explanationNe":"SNP भनेको genome को एक nucleotide स्थानमा हुने variation हो।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
('bmlt-moleculargenetics1-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"DNA sequencing determines:","translation":"","options":["The order of nucleotides in DNA","The concentration of glucose","The shape of red cells","The pH of plasma"],"correctIndex":0,"explanation":"Sequencing identifies the nucleotide order in a DNA molecule.","explanationNe":"Sequencing ले DNA मा nucleotide को क्रम पत्ता लगाउँछ।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
('bmlt-moleculargenetics1-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"A karyotype is most useful for detecting:","translation":"","options":["Large chromosomal number or structural abnormalities","Single-base changes routinely","Serum enzyme activity","Bacterial antibiotic susceptibility"],"correctIndex":0,"explanation":"Karyotyping visualizes chromosomes and detects large-scale changes.","explanationNe":"Karyotype ले chromosome संख्या वा ठूला संरचनात्मक परिवर्तन देखाउँछ।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
