('bmlt-moleculargenetics1-mock-009','BMLT','BMLT NHPC Licensing','mock','free',9,'{"question":"A nucleotide substitution creates a premature stop codon. This is a:","translation":"","options":["Nonsense mutation","Silent mutation","Missense mutation","Duplication"],"correctIndex":0,"explanation":"A nonsense variant introduces a stop codon prematurely.","explanationNe":"Nonsense mutation ले समयभन्दा पहिले stop codon बनाउँछ।","topic":"Molecular Diagnostics & Clinical Genetics"}'::jsonb,true),
